\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 164\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -165\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo in capite ieiunii}}\plain \f1\b\lang1033\fs24  (nach {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Jordanus de Quedlinburg}}\plain \f1\b\lang1033\fs24  oder {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes Contractus}}\plain \f1\b\lang1033\fs24 ?)\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >S<{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 edit populus meus manducare et bibere}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  (I Cor 10,7).\plain \f1\i\lang1033\fs24  Hoc uerbum sumptum est Exodum et hodie\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 in ecclesia dei hoc adimpletur, quia hodie homines commedunt et bibunt ... Nota, quod homines in hoc tempore solent excedere in multis, precipue in quatuor: primo gulose manducare\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 secundo nimis bibere, tercio uana cantare, quarto choreas ducere. ... - ... ego in cruce dolui et tu in cruce exultas. Tamen reuertere ad me et ego suscipiam te\plain \f1\lang1033\fs24  (Ier 3,1)\plain \f1\i\lang1033\fs24 . Amen.\plain \f1\lang1033\fs24  Rest der Spalte leer.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 \u196 \'c4hnlich \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Repertorium, Bd. 3, S. 830, Nr. 192 (\plain \f1\scaps\lang1033\fs20 Jordanus de Quedlinburg\plain \f1\lang1033\fs20 : Sermones de tempore, Series 2) und S. 435, Nr. 27 (\plain \f1\scaps\lang1033\fs20 Johannes Contractus OM\plain \f1\lang1033\fs20 : Sermones). \u196 \'c4hnliches Incipit auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 W\u252 \'fcrzburg, UB, M. ch. q. 12}}\plain \f1\lang1033\fs20 , 349\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  (vor dem Text De meritis sanctorum, s. o. 94\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 ), vgl. \plain \f1\scaps\lang1033\fs20 Thurn, \plain \f1\lang1033\fs20 W\u252 \'fcrzburg V, S. 163.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

