\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (120\plain \f1\super\lang1033\fs24 ra-va\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 Urbanus papa I. (25.01.)\plain \f1\i\lang1033\fs24 . >U<{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 rbanus episcopus, nacione Romanus, beati Petri apostoli tercius decimus vicarius fuit}}\plain \f1\i\lang1033\fs24 . Hic ante episcopatum probabilis fuit confessor ... - ... miracula usque in hodiernum diem.\plain \f1\lang1033\fs24 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (120\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -121\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  >Vita sancti Erasmi<. \plain \f1\lang1033\fs24 (03.06.)\plain \f1\i\lang1033\fs24 . >S<{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 anctus Erasmus audiens persecucionem Christianorum heremum peciit}}\plain \f1\i\lang1033\fs24  ... - ... et iussit eum gladio puniri et requieuit in pace, prestante domini Christi, qui cum.\plain \f1\lang1033\fs24 ;
