\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 250\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -282\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Humbertus de Prulliaco OCist}}\plain \f1\b\lang1033\fs24 .: {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Commentarius in Sententias Petri Lombardi}}\plain \f1\b\lang1033\fs24  (Conclusiones in libros IV Sententiarum)\plain \f1\lang1033\fs24 , unvollst\u228 \'e4ndig.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 [Q]{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Voniam in paucioribus via ideo magis}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 [sonst: magis, ideo] \plain \f1\i\lang1033\fs24 scripta sententiarum communia cogitaui fore congruum questionum omnium conclusiones cum breui declaratione ... colligere ... Questio prima. \plain \f1\lang1033\fs24 [P]\plain \f1\i\lang1033\fs24 Rimo igitur de subiecto theologie solet queri, et primo, utrum idem sit esse subiectum in scientia et esse de consideratione sciencie ...\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (250\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -273\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) [Commentum in librum I.:]\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 [Q]\plain \f1\i\lang1033\fs24 Vesito circa prologum restat querere circa primam distinctionem. Circa quam primo queritur: Cuius actus sit frui ...\plain \f1\lang1033\fs24 , (274\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -282\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) [Commentum in librum II.:]\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 [C]\plain \f1\i\lang1033\fs24 Irca secundum librum primo queritur, utrum sint plura principia. Dicendum quod non ... - ... quod serpens dicebat, quando\plain \f1\lang1033\fs24  [..., bricht in Dist. 22 von Buch II ab].
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Teiledition: Clemens \plain \f1\scaps\lang1033\fs20 Heidack\plain \f1\lang1033\fs20 , Humbert von Preuilly (\u8224 \'86 1298), einer der \u228 \'e4ltesten thomasischen Denker. Eine philosophiehistorische Untersuchung mit Textbeilagen aus dem unedierten Sentenzenkommentar Humberts und den \u8222 \'84Quaestiones diversarum opinionum\ldblquote , die dem Humbert zugeschrieben werden, Diss. Bonn 1965, 113-138. Zur \u220 \'dcberlieferung (ohne diese Hs.) vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17\cf1 Stegm\u252 \'fcller, RS, Nr. 380}}\plain \f1\lang1033\fs20\cf1 . Zum Autor (bacc. theol. am Ordensstudium St. Bernhard in Paris, vor 1294 Sentenzenvorlesungen, ab 1296 Abt des Zisterzienserklosters Prully, Bm. Sens, \u8224 \'86 1298) vgl. \plain \f1\scaps\lang1033\fs20 Heidack\plain \f1\lang1033\fs20 , ebd., S. 21-23; F. W. \plain \f1\scaps\lang1033\fs20 Bautz\plain \f1\lang1033\fs20 , in BBKL II (1990), Sp. 1163;\plain \f1\lang1033\fs20\cf1  L. \plain \f1\scaps\lang1033\fs20 H\plain \f1\scaps\lang1033\fs20 \u246 \'f6\plain \f1\scaps\lang1033\fs20 dl\plain \f1\lang1033\fs20 , in: LexMA V (1991), Sp. 208f;\plain \f1\scaps\lang1033\fs20  Weijers\plain \f1\lang1033\fs20 , Travail intellectuel 4, S. 95-97, mit weiterer Lit.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 \par}

