\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (327\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Thomas Lam}}\plain \f1\b\lang1033\fs24 : Gliederung und Beginn einer {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Repetitio}}\plain \f1\b\lang1033\fs24  zu {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Decretales}}\plain \f1\b\lang1033\fs24  Gregorii papae IX., lib. III, tit. 32, cap. 2\plain \f1\lang1033\fs24  (nach 1451/52 und vor 1467).
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 [am oberen Seitenrand: \plain \f1\i\lang1033\fs24 Bacc. Lam\plain \f1\lang1033\fs24 ]. \plain \f1\i\lang1033\fs24 Ex c. \u8218 \'82Verum\lquote  de \u8218 \'82De conuersione coniugatorum\lquote \plain \f1\lang1033\fs24  [= X III,32,2: Verum post consensum legitimum ..., vgl. \plain \f1\scaps\lang1033\fs24 Friedberg\plain \f1\lang1033\fs24  II, Sp. 579]. \plain \f1\i\lang1033\fs24 Conclusio prima: Legittimum coniugium, quod duorum contrahencium \plain \f1\lang1033\fs24 ... \plain \f1\i\lang1033\fs24 Venerabilis domine baccalaureate\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Quamuis positio uestra sit canonice et iuridice cum conclusionibus ... Contra primam conclusionem arguo sic ...\plain \f1\lang1033\fs24 , bricht am Seitenende ab. 328\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 Thomas Lam aus Magdeburg\plain \f1\lang1033\fs20 , SS 1447 imm., WS 1451/52 bacc. art., vor 1467 Dr. decr., 1467 Rektor, vgl. \plain \f1\scaps\lang1033\fs20 Gersdorf\plain \f1\lang1033\fs20 , Rectoren Leipzig\plain \f1\scaps\lang1033\fs20 , S. 28, \plain \f1\lang1033\fs20 Nr.\plain \f1\scaps\lang1033\fs20  116; \plain \f1\scaps\lang1033\fs20 Erler,\plain \f1\lang1033\fs20  Matrikel Leipzig II, S. 37; \plain \f1\scaps\lang1033\fs20 Friedberg\plain \f1\lang1033\fs20 , Leipziger Juristenfakult\u228 \'e4t, S. 123 (Doktorenverz., Nr. 17); \plain \f1\scaps\lang1033\fs20\cf1 Wejwoda\plain \f1\lang1033\fs20\cf1 , Leipziger Juristenfakult\u228 \'e4t, S. 68 mit Anm. 348. \plain \f1\lang1033\fs20 Lam hatte von 1475 bis 1478 (\u8224 \'86) ein Universit\u228 \'e4tskanonikat im Merseburger Domkapitel inne, vgl. \plain \f1\scaps\lang1033\fs20 Cottin\plain \f1\lang1033\fs20 , Leipziger Universit\u228 \'e4tskanonikate, S. 312.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (328\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -332\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Repetitio}}\plain \f1\b\lang1033\fs24  zu {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Decretales}}\plain \f1\b\lang1033\fs24  Gregorii papae IX., lib. I, tit. 38, cap. 13 (WS 1464/65)\plain \f1\lang1033\fs24 . 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 In nomine sancte et indiuidue trinitatis ... amen. Repetiturus decretalem \lquote Mandato\rquote  sub titulo \lquote De procura\plain \f1\lang1033\fs24 [toribus = X I,38,13, vgl. \plain \f1\scaps\lang1033\fs24 Friedberg\plain \f1\lang1033\fs24  II, Sp. 217] \plain \f1\i\lang1033\fs24 situatam solitum ordinem more repetencium seruabo. Primo breuem diuini nominis inuocacionem premittam, secundo ad decretalem meam accedam et eam more repetencium expediam ...\plain \f1\lang1033\fs24 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (332\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) [Danksagung:] \plain \f1\i\lang1033\fs24 Quantum ad ultimum ... restat referre graciarum acciones ... \plain \f1\lang1033\fs24 (332\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 In primis nomine nouellorum baccalaureorum et meo regracior venerabili viro domino et magistro \plain \f1\b\i\lang1033\fs24 Thome Werneri de Brunsbergk\plain \f1\i\lang1033\fs24 , sacre theologie baccalaureo, huius alme universitatis rectori dignissimo ... Regraciamus insuper nobili domino ac generoso \plain \f1\b\i\lang1033\fs24 comiti N. de Slik\plain \f1\i\lang1033\fs24 , qui eciam personaliter hunc actum decorauit. Denique regraciamus venerabili patri domino et magistro \plain \f1\b\i\lang1033\fs24 Iohanni Grundemann\plain \f1\i\lang1033\fs24 , sacre theologie baccalaureo formato, huius monasterii sancti Thome preposito ..., venerabilibus eciam viris et dominis sacre theologie professoribus ... domino et magistro \plain \f1\b\i\lang1033\fs24 Gregorio Steynbrechir\plain \f1\i\lang1033\fs24 , domino \plain \f1\b\i\lang1033\fs24 Thymoni Pazerin\plain \f1\i\lang1033\fs24 , \plain \f1\b\i\lang1033\fs24 Iohanni Schu\plain \f1\b\i\super\lang1033\fs24 e\plain \f1\b\i\lang1033\fs24 rlin\plain \f1\i\lang1033\fs24 , magistro \plain \f1\b\i\lang1033\fs24 Johanni Ebernhusin\plain \f1\i\lang1033\fs24  et domino \plain \f1\b\i\lang1033\fs24 Thome Lame\plain \f1\i\lang1033\fs24 , iuridice facultatis doctoribus ... Regraciamus denique egregiis viris medicine doctoribus, venerabili viro magistro \plain \f1\b\i\lang1033\fs24 Johanni de Rudisheim\plain \f1\i\lang1033\fs24 , sacre theologie baccalaureo formato facultatis arcium decano, ... et magistro \plain \f1\b\i\lang1033\fs24 Johanni Schyben\plain \f1\i\lang1033\fs24 , in decretorum licenciato, ... Ad laudem dei. Amen.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Thomas Werneri}}\plain \f1\b\lang1033\fs20  de Braunsbergk\plain \f1\lang1033\fs20 , 1448 imm., 1454 mag., 1479 Lizenziat und 1483 Doktor der Theologie, Mitglied und 1459 Propst des Kleinen F\u252 \'fcrstenkollegs, wechselte 1471 an das Gro\u223 \'dfe F\u252 \'fcrstenkolleg (1480 Propst) und zwischen 1493-98 in das Collegium BMV, 1461 und 1479 Dekan der Artistenfakult\u228 \'e4t, WS 1464/65\plain \f1\b\lang1033\fs20  \plain \f1\lang1033\fs20 Rektor, \u8224 \'86 23.12.1498, vgl. \plain \f1\scaps\lang1033\fs20 Kusche\plain \f1\scaps\lang1033\fs20 ,\plain \f1\lang1033\fs20  Magisterkollegien, S. 818-821, Nr. 200, mit weiteren Nachweisen; zu seiner Wahl zum Rektor vgl. \plain \f1\scaps\lang1033\fs20 Gersdorf\plain \f1\lang1033\fs20 , Rectoren Leipzig\plain \f1\scaps\lang1033\fs20 , S. 28, \plain \f1\lang1033\fs20 Nr. \plain \f1\scaps\lang1033\fs20 111; \plain \f1\scaps\lang1033\fs20 Erler,\plain \f1\lang1033\fs20  Matrikel Leipzig I, S. LXXVI und 247. Bedeutung f\u252 \'fcr die Leipziger Universit\u228 \'e4tsgeschichte erlangte er vor allem durch seinen umfangreichen Buchbesitz, von dem ein gro\u223 \'dfer Teil erhalten ist. Vgl. Theresa \plain \f1\scaps\lang1033\fs20 Borawska\plain \f1\lang1033\fs20  / Henryk \plain \f1\scaps\lang1033\fs20 Rietz\plain \f1\lang1033\fs20 , Die Bibliothek des Leipziger Professors Thomas Werner (gest. 1498) aus Braunberg in Preu\u223 \'dfen, in: Jan \plain \f2\scaps\lang1024\fs20 Piro\plain \f2\scaps\lang1024\fs20 \u380 \'bf\plain \f2\scaps\lang1024\fs20 ynski\plain \f1\lang1033\fs20  (Hg.), Beitr\u228 \'e4ge der polnischen Stipendiaten der Herzog-August-Bibliothek zur Philosophie, Geschichte und Philologie, Krakau 1994, S. 93-110.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Comes de S(ch)lik}}\plain \f1\lang1033\fs20 : Angeh\u246 \'f6riger eines aus Eger stammenden Freiherrengeschlechts, dessen ber\u252 \'fchmtester Vertreter Kaspar Schlick (um 1396-1449), Kanzler der K\u246 \'f6nige Sigismund (1411-37), Albrecht II. (1438/39) und Friedrich III. (ab 1440) war; die Familie f\u252 \'fchrte seit ca. 1437 den nominellen Titel eines Reichsgrafen von Bassano (Venetien) und war im Besitz der Pfandherrschaft des nordwestb\u246 \'f6hmischen Kreises Elbogen sowie der ungarischen Burgherrschaft Wei\u223 \'dfkirchen / Neuschloss (Skalitz im oberen Waagtale); mehrere Vertreter der Familie studierten an der Leipziger Universit\u228 \'e4t, so z. B. im WS 1464/65{\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17  Hieronymus}}\plain \f1\b\lang1033\fs20  und {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Georg Schlick}}\plain \f1\b\lang1033\fs20 ,\plain \f1\lang1033\fs20  in der Matrikel aufgef\u252 \'fchrt als \u8222 \'84nobilis dominus Ieronimus / Georius Sligk de Lasano comes et dominus Novicastri et Stolbergk\ldblquote , vgl. \plain \f1\scaps\lang1033\fs20 Erler,\plain \f1\lang1033\fs20  Matrikel Leipzig I, S. 247; Georg Schlick studierte seit SS 1470 in Wien, vgl. \u8218 \'82Georg Schlick, gen. Lazan\lquote , in: RAG, Repertorium Academicum Germanicum. http://www.rag-online.org/gelehrter/id/-1293241206 (05.04.2013). Zur Familie vgl. Franz \plain \f1\scaps\lang1033\fs20 Fuchs\plain \f1\lang1033\fs20 , Art. \u8222 \'84Schlick, Kaspar\ldblquote , in: NDB 23 (2007), S. 77f.; Uwe \plain \f1\scaps\lang1033\fs20 Tresp\plain \f1\lang1033\fs20 , Zwischen B\u246 \'f6hmen und Reich, St\u228 \'e4nden und K\u246 \'f6nigtum. Integration und Selbstverst\u228 \'e4ndnis der Grafen Schlick in B\u246 \'f6hmen um 1500, in: Eva \plain \f1\scaps\lang1033\fs20 Schlotheuber\plain \f1\lang1033\fs20  / Hubertus \plain \f1\scaps\lang1033\fs20 Seibert\plain \f1\lang1033\fs20  (Hg.), B\u246 \'f6hmen und das Deutsche Reich. Ideen- und Kulturtransfer im Vergleich (13.-16. Jahrhundert), M\u252 \'fcnchen 2009 (Ver\u246 \'f6ffentlichungen des Collegium Carolinum 116), S. 177-202, hier v. a. S. 184-186.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Johannes Grundemann,}}\plain \f1\lang1033\fs20  1439 imm., 1442 mag., danach Studium an der Theologischen Fakult\u228 \'e4t (1454 Sententiarius, 1458 Lizenziat), am 13.01.1454 erstmals urkundlich als Propst des Thomasstiftes genannt, \u8224 \'86 14.01.1470, vgl. \plain \f1\scaps\lang1033\fs20 Mackert\plain \f1\lang1033\fs20 , Leipziger Textsammlung, S. 249-251, mit Verweis auf weitere Lit.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[5].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Gregor Steinbrecher}}\plain \f1\lang1033\fs20  \plain \f1\b\lang1033\fs20 aus Striegau\plain \f1\lang1033\fs20 , 1441 imm., 1444 mag., vor 1450 decretorum doctor, WS 1450/51 Rektor, 1458-65 Mitglied des Gro\u223 \'dfen F\u252 \'fcrstenkollegs, 1459 dessen Propst, 1467-1506 Dekan des Merseburger Domkapitels, \u8224 \'86 1506, vgl. \plain \f1\scaps\lang1033\fs20 Gersdorf\plain \f1\lang1033\fs20 , Rectoren Leipzig\plain \f1\scaps\lang1033\fs20 , S. 26, \plain \f1\lang1033\fs20 Nr. \plain \f1\scaps\lang1033\fs20 83; \plain \f1\scaps\lang1033\fs20 Friedberg\plain \f1\lang1033\fs20 , Leipziger Juristenfakult\u228 \'e4t, S. 123 (Doktorenverz., Nr. 12); \plain \f1\scaps\lang1033\fs20 Kusche\plain \f1\scaps\lang1033\fs20 ,\plain \f1\lang1033\fs20  Magisterkollegien, S. 534f., Nr. 31; \plain \f1\scaps\lang1033\fs20\cf1 Wejwoda\plain \f1\lang1033\fs20\cf1 , Leipziger Juristenfakult\u228 \'e4t, S. 115, Nr. 30,\plain \f1\lang1033\fs20  mit weiteren Nachweisen;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[6].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Thimo von Paserin }}\plain \f1\b\lang1033\fs20 aus Luckau\plain \f1\lang1033\fs20 , 1427 imm., vor WS 1453/54 Dr. decr., Rektor WS 1453, danach mehrfach als Rechtslehrer der Juristenfakult\u228 \'e4t erw\u228 \'e4hnt, 1466-69 Dekan des Kollegiatsstifts Zeitz, \u8224 \'86 1469, vgl. \plain \f1\scaps\lang1033\fs20 Erler,\plain \f1\lang1033\fs20  Matrikel Leipzig II, S. 37; \plain \f1\scaps\lang1033\fs20 Friedberg\plain \f1\lang1033\fs20 , Leipziger Juristenfakult\u228 \'e4t, S. 123 (Doktorenverz., Nr. 13); \plain \f1\scaps\lang1033\fs20\cf1 Wejwoda\plain \f1\lang1033\fs20\cf1 , Leipziger Juristenfakult\u228 \'e4t, S. 116, Nr. 31,\plain \f1\lang1033\fs20  mit weiteren Nachweisen;\plain \f1\lang1033\fs20\cf1  
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[7].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Johannes Scheuerl }}\plain \f1\b\lang1033\fs20 (Schewerlein) aus Lauingen\plain \f1\lang1033\fs20 , WS 1448/49 imm., Rechtsstudium und vor SS 1458 lic. decr., SS 1458 Rektor, vor 12.08.1460 Dr. decr., 1458 bis mind. 1470 Rechtslehrer in Leipzig, \u8224 \'86 1476, vgl. \plain \f1\scaps\lang1033\fs20 Erler,\plain \f1\lang1033\fs20  Matrikel Leipzig II, S. 37; \plain \f1\scaps\lang1033\fs20 Friedberg\plain \f1\lang1033\fs20 , Leipziger Juristenfakult\u228 \'e4t, S. 123 (Doktorenverz., Nr. 15); \plain \f1\scaps\lang1033\fs20\cf1 Wejwoda\plain \f1\lang1033\fs20\cf1 , Leipziger Juristenfakult\u228 \'e4t, S. 117, Nr. 33,\plain \f1\lang1033\fs20  mit weiteren Nachweisen;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[8].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Johannes Eberhausen}}\plain \f1\b\lang1033\fs20  aus G\u246 \'f6ttingen\plain \f1\lang1033\fs20 , 1450 imm. in Rostock, SS 1451 in Leipzig, WS 1454 mag. art., 1460 Rechtsstudium in Bologna und Promotion zum Dr. decr., SS 1463 Rektor in Leipzig, 1470-79 Ordinarius der Juristenfakult\u228 \'e4t, Rechtsberater der Stadt Leipzig, ab 1478 Universit\u228 \'e4tskanonikat im Naumburger Domkapitel, \u8224 \'86 1479, vgl. \plain \f1\scaps\lang1033\fs20 Erler,\plain \f1\lang1033\fs20  Matrikel Leipzig II, S. 37; \plain \f1\scaps\lang1033\fs20 Friedberg\plain \f1\lang1033\fs20 , Leipziger Juristenfakult\u228 \'e4t, S. 114 (Ordinarienverz., Nr. 7), S. 123 (Doktorenverz., Nr. 16); \plain \f1\scaps\lang1033\fs20 Cottin\plain \f1\lang1033\fs20 , Leipziger Universit\u228 \'e4tskanonikate, S. 312; \plain \f1\scaps\lang1033\fs20\cf1 Wejwoda\plain \f1\lang1033\fs20\cf1 , Leipziger Juristenfakult\u228 \'e4t, S. 117f., Nr. 34,\plain \f1\lang1033\fs20  mit weiteren Nachweisen;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[9].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Thomas Lam }}\plain \f1\b\lang1033\fs20 aus Magdeburg\plain \f1\lang1033\fs20 , s. o. 327\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20\cf1 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[10].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Johannes Faber}}\plain \f1\b\lang1033\fs20  aus R\u252 \'fcdisheim\plain \f1\lang1033\fs20 , seit 1442 Studium in Wien, SS 1448 imm. in Leipzig, 1451 mag. art., Studium der Theologie: 1458 Kursor, 1461 Sententiar, SS 1464 Rektor, WS 1464/65 Dekan der Artistenfakult\u228 \'e4t, seit 1470 Mitglied des Liebfrauenkollegs, \u8224 \'86 um 1479, vgl. \plain \f1\scaps\lang1033\fs20 Erler,\plain \f1\lang1033\fs20  Matrikel Leipzig II, S. 194; \plain \f1\scaps\lang1033\fs20 Kusche\plain \f1\scaps\lang1033\fs20 ,\plain \f1\lang1033\fs20  Magisterkollegien, S. 601f., Nr. 75\plain \f1\lang1033\fs20\cf1 ,\plain \f1\lang1033\fs20  mit weiteren Nachweisen;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[11].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Johannes Scheibe}}\plain \f1\b\lang1033\fs20  aus Leipzig\plain \f1\lang1033\fs20 , SS 1437 imm., WS 1442 mag. art., vor 1464 Dr. decr. und 1464-70 Ordinarius der Juristenfakult\u228 \'e4t, 1470-77 Kanzler der s\u228 \'e4chsischen Kurf\u252 \'fcrsten Albrecht und Ernst, \u8224 \'86 1479, vgl. \plain \f1\scaps\lang1033\fs20 Erler,\plain \f1\lang1033\fs20  Matrikel Leipzig II, S. 37; \plain \f1\scaps\lang1033\fs20 Friedberg\plain \f1\lang1033\fs20 , Leipziger Juristenfakult\u228 \'e4t, S. 114 (Ordinarienverz., Nr. 6); \plain \f1\scaps\lang1033\fs20\cf1 Wejwoda\plain \f1\lang1033\fs20\cf1 , Leipziger Juristenfakult\u228 \'e4t, S. 118, Nr. 35,\plain \f1\lang1033\fs20  mit weiteren Nachweisen.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Rest von 332\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  und 333\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \par}

