\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 102\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -103\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  [Nachtrag vom Schreiber:] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo de novo sacerdote}}\plain \f1\b\lang1033\fs24  (Exhortatio pro commendatione dignitatis sacerdotum)\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Vos estis genus electum }}\plain \f1\i\lang1033\fs24 ... \plain \f1\lang1033\fs24 (I Pt 2,9). \plain \f1\i\lang1033\fs24 Hec uerba beati Petri. Vos, qui estis sacerdotes domini, ministri dei vivi, vos estis, inquam, genus electum et preelectum ... - ... tristicia uestra vertetur in gaudium, gaudium vestrum\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 nemo tollat\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 a uobis. Amen.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Jena, ThULB, Ms. Klosterbibl. 5 }}\plain \f1\lang1033\fs20 (Th\u252 \'fcringen, 1431-33, geschrieben von einem Kleriker, der Kaplan in Magdala, Oberweimar und Erfurt war), 83\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 , vgl. \plain \f1\scaps\lang1033\fs20 Klein-Ilbeck/Ott\plain \f1\lang1033\fs20 , Jena 2, S. 258, sowie in {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Hildesheim, Domb, J 88, 22}}\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  (Burg bei Magdeburg, ca. 1468/74), vgl. \plain \f1\scaps\lang1033\fs20 Giermann/H\plain \f1\scaps\lang1033\fs20 \u228 \'e4\plain \f1\scaps\lang1033\fs20 rtel\plain \f1\lang1033\fs20 , Hildesheim II, S. 241, hier als \lquote Exortacio pro commendacione dignitatis sacerdotum\rquote .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

