\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -359\plain \f1\super\lang1033\fs24 va\plain \f1\b\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Nicolaus de Tudeschis}}\plain \f1\b\lang1033\fs24  (Panormitanus): {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Lectura super libro secundo Decretalium}}\plain \f1\b\lang1033\fs24 , Pars II (X 2.19.1-X.2.24.36).
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -68\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) [X.2.19.1-15: \plain \f1\b\lang1033\fs24 De probationibus\plain \f1\lang1033\fs24 :] 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >H<Ec rubrica satis continuata fuit supra in precedenti \plain \f1\lang1033\fs24 [sonst: rubrica]\plain \f1\i\lang1033\fs24 , sed magis specialiter potest sic continuari. Supra in precedenti titulo uisum est de confessionibus, per quas aduersarius releuatur ab onere probandi ... \plain \f1\lang1033\fs24 (1\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 ... \plain \f1\lang1033\fs24 [cap. 1]\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >E<X epistole. Casus: Reus actori sua propria instrumenta edere non tenetur}}\plain \f1\i\lang1033\fs24  ... - ... vel aliter expirasset iurisdiccio primi iudicis. Et hec sufficiant. Sequitur rubrica de testibus.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Druck 1476 (s. u.), Bl. 1\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 -41\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 ; Grundtext: \plain \f1\scaps\lang1033\fs20 Friedberg\plain \f1\lang1033\fs20  II, Sp. 306-315;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (68\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -178\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) [X.2.20.1-51: \plain \f1\b\lang1033\fs24 De testibus et attestationibus\plain \f1\lang1033\fs24 :] 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Druck 1476 (s. u.), Bl. 41\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 -101\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 ; Grundtext: \plain \f1\scaps\lang1033\fs20 Friedberg\plain \f1\lang1033\fs20  II, Sp. 315-340;
