\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 NT\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Matheus. }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [N]}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 atus, adoratur, lotum, temptat, docet, orat}}\plain \f1\i\lang1033\fs24 , ...\plain \f1\lang1033\fs24  bis (144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 ... Johannis: \plain \f1\lang1033\fs24 [V]\plain \f1\i\lang1033\fs24 erbum, mutat aquas, Nicodemus, ydra, motus ... - ... Illusus, moritur, surrexit, se manifestat.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Merkverse zu den \u252 \'fcber 1200 Kapiteln der Bibel, \u252 \'fcber den einzelnen W\u246 \'f6rtern jeweils Kapitelnummer und Glosse. Von dem insgesamt aus 212 Hexametern bestehenden Werk (Inc. Gn: Sex, prohibet, peccant, Abel, Enoch, archa fit, intrant ...) hier nur der Schlussteil zum AT (I-IV Rg, I-III Esr, Tb, Idt, Est) sowie die Passage zu den vier Evangelien \u252 \'fcberliefert.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Druck (mit abweichenden Interlinearglossen): Biblia cu[m] pleno apparatu summariorum co[n]cordantiaru[m] [...]. Basel: Petri, Joh., Amerbach, Joh. und Froben, Joh., 1509, Tabula III, Bl. 3\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -8\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , vgl. VD16 B 2584 und Digitalisat: \plain \f1\lang1033\fs20\cf1 http://daten.digitale-sammlungen.de/~db/bsb00001921/image_8\plain \f1\lang1033\fs20 . Zu weiteren Drucken vgl. \plain \f1\scaps\lang1033\fs20 Sch\plain \f1\scaps\lang1033\fs20 \u246 \'f6\plain \f1\scaps\lang1033\fs20 nberger/Kible, \plain \f1\lang1033\fs20 Repertorium, S. 288. Zur Verfasserfrage und zum Werk vgl. Dietrich \plain \f1\scaps\lang1033\fs20 Reichling\plain \f1\lang1033\fs20  (Hg.), Das Doctrinale des Alexander de Villa Dei, Berlin 1893, S. XLIIf.; Wolfgang \plain \f1\scaps\lang1033\fs20 Maaz\plain \f1\lang1033\fs20 , Zur Rezeption des Alexander von Villa Dei im 15. Jahrhundert, in: Mittellat. Jb. 16 (1981), S. 276-281; Peter \plain \f1\scaps\lang1033\fs20 Stotz\plain \f1\lang1033\fs20 , Bibeldichtung als Bibel-Verdichtung [...], in: Christian \plain \f1\scaps\lang1033\fs20 Moser\plain \f1\lang1033\fs20  / Peter \plain \f1\scaps\lang1033\fs20 Opitz\plain \f1\lang1033\fs20  (Hg.), Bewegung und Beharrung. Aspekte des reformierten Protestantismus, Leiden 2009, S. 259-282, hier S. 270. Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 , RB 8,2, Nr. 1175-1182,2}}\plain \f1\lang1033\fs20  (Varianten); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Walther}}{\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 , Carmina, Nr. 17610}}\plain \f1\lang1033\fs20 .}

