\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 220\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -222\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Expositio allegationum iuris}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >Sequitur alphabetum iuris<. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 \lquote Ignorantia facti, non iuris, excusat\rquote }}\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sexti Decretales}}\plain \f1\lang1033\fs24 , V.12, Reg. iuris XIII, vgl. \plain \f1\scaps\lang1033\fs24 Friedberg\plain \f1\lang1033\fs24  II, Sp. 1122). \plain \f1\i\lang1033\fs24 Sic scribitur Extra \lquote De regulis iuris\rquote , capitulo \lquote Ignorantia\rquote , libro vi.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 In hiis verbis breviter tanguntur duo articuli principales ...\plain \f1\lang1033\fs24 ; (220\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -221\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) [Allegationen:] \plain \f1\i\lang1033\fs24 Al: id est Albertus Teutonicus. Ala: id est Alanus. ... Vincen: id est Vincentinus. \plain \f1\lang1033\fs24 \u182 \'b6\plain \f1\i\lang1033\fs24 : id est paragrafus. Est autem secundum Gratianum ... - ... in capitulo, quod incipit \u8218 \'82Si quis suadente\plain \f1\lang1033\fs24  [diabolo, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Decretum Gratiani}}\plain \f1\lang1033\fs24 , II, 17,4,29, vgl. \plain \f1\scaps\lang1033\fs24 Friedberg\plain \f1\lang1033\fs24  I, Sp. 822]\plain \f1\i\lang1033\fs24 \rquote  etc.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Halle, ULB, Qu. Cod. 131 (Erfurt, um 1427), 34r-35}}\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , vgl. \plain \f1\scaps\lang1033\fs20 Fliege\plain \f1\lang1033\fs20 , Quedlinburg, S. 233; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Greifswald, Bibl. d. Geistl. Ministeriums, 18.C.I. (um 1427), 16ra-18}}\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 , vgl. \plain \f1\lang1033\fs20\cf1 http://www.manuscripta-mediaevalia.de/dokumente/html/obj31275010,T\plain \f1\lang1033\fs20 , mit Digitalisat.}

