\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >D<Einde sumatur extractum de tractatu de penitentiis, ubi sic allegatur}}\plain \f1\i\lang1033\fs24 : De penitencia distinctione iij \lquote Caritas\rquote  i in secunda parte Decreti \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Decretum Gratiani}}\plain \f1\lang1033\fs24 , II, 33,3, vgl. \plain \f1\scaps\lang1033\fs24 Friedberg\plain \f1\lang1033\fs24  I, Sp. 1211)\plain \f1\i\lang1033\fs24 , quod solet sic bre\plain \f1\lang1033\fs24 (222\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 uiari: de. pe. dis. iij Caritas i in 2a parte Decreti ... - ... in capitulo, qui sic incipit \lquote Firmissime\rquote \plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Decretum Gratiani}}\plain \f1\lang1033\fs24 , III, 4,3, vgl. \plain \f1\scaps\lang1033\fs24 Friedberg\plain \f1\lang1033\fs24  I, Sp. 1362)\plain \f1\i\lang1033\fs24 .}

