\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >In prohemio huius<}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  (235ra) }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 capituli queruntur ista: Quid sit fides}}\plain \f1\i\lang1033\fs24 . An obiectum fidei sit complexum aut incomplexum. Quot sint articuli fidei. ... - ... An beatitudo eterna consistat principaliter in visione. Sic est finis et quasi \plain \f1\lang1033\fs24 (?) \plain \f1\i\lang1033\fs24 sunt in numero 275 etc.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Koblenz, LHA, Best. 701 Nr. 216 (Basel, um 1390), 219}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs20\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 -223}}\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , vgl. \plain \f1\scaps\lang1033\fs20 Overgaauw\plain \f1\lang1033\fs20 , LHA Koblenz II, S. 143.}

