\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 237\plain \f1\super\lang1033\fs24 rb-vb\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Privilegia clericorum}}\plain \f1\b\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Incipiunt priuilegia clericorum. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >P<Rimo percuciens clerum est}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 [...]\plain \f1\i\lang1033\fs24  xvii, qui in \lquote Si quis \plain \f1\lang1033\fs24 [in aliquos gradu]\plain \f1\i\lang1033\fs24 \rquote  \plain \f1\lang1033\fs24 (X.5.25,1, vgl. \plain \f1\scaps\lang1033\fs24 Friedberg\plain \f1\lang1033\fs24  II, Sp. 825)\plain \f1\i\lang1033\fs24 . Item capiens clerum sine lesione corporali: \lquote De sen\plain \f1\lang1033\fs24 [tentia] \plain \f1\i\lang1033\fs24 ex\plain \f1\lang1033\fs24 [commonicationis] (X.5.39, vgl. ebd., Sp. 889)\plain \f1\i\lang1033\fs24 \rquote ... Item clerus potest se probari percussum cum uno teste\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 ... - ... questione prima si vero. Sic est finis.}

