\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >I<n corpore Christi gloriosa decem miracula sunt. Primum est, quod panis}}\plain \f1\i\lang1033\fs24  et vinum transsubstan\plain \f1\lang1033\fs24 (238\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 tiantur in corpus et sanguinem domini nostri Ihesu Christi. Comparatio huius est ... - ... uirtus spiritualis est ipsa caritas.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Koblenz, LHA, Best. 701 Nr. 138 (Mittel- und Westdeutschland, 15. Jh., 1. Viertel), 74}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs20\chcbpat17 va-vb}}\plain \f1\lang1033\fs20 , vgl. \plain \f1\scaps\lang1033\fs20 Meckelnborg\plain \f1\lang1033\fs20 , LHA Koblenz I, S. 218.}

