\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 289\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -305\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Nicolaus de Lyra}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Disputatio super concordantiam evangelistarum}}\plain \f1\b\lang1033\fs24  (Responsio ad quendam Judaeum)\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 [\u220 \'dcberschrift in Textura: \plain \f1\i\lang1033\fs24 Incipit disputacio Nicolay de Ly\plain \f1\lang1033\fs24 (ra)]\plain \f1\i\lang1033\fs24 . Incipit disputacio Nicolai de Lira contra Iudeos super concordanciam ewangelistarum.\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [Ut]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  potens sit }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [et] }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ex}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [h]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ortari in doctrina sana}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  (Tit 1,9). \plain \f1\i\lang1033\fs24 Licet verbum propositum episcopalis condicionis sit expressivum, convenienter tamen potest accipi, ut sit expressivum perfectionis katholici doctoris.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 ... - ... obiectiones suas in aperto mendacio terminavit. Explicit responsio fratris Nicolay de Lyra ad quendam Iudeum ex verbis evangelii secundum Matthaeum contra Christum nequiter arguentem. Amen anno domini M cccc xiii\u176 \'b0.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Druck: Venedig 1589, Bd. IV, S. 280-285. Zur \u220 \'dcberlieferung (ohne diese Hs.) vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 , RB IV, Nr. 5980}}\plain \f1\lang1033\fs20 ; \plain \f1\scaps\lang1033\fs20 Glorieux,\plain \f1\lang1033\fs20  Mai\plain \f2\lang1033\fs20 \u770 ?\plain \f1\lang1033\fs20 tres en th\u233 \'e9ologie II\plain \f1\scaps\lang1033\fs20 , S. 223, \plain \f1\lang1033\fs20 Nr. 345i\plain \f1\scaps\lang1033\fs20 ; \plain \f1\scaps\lang1033\fs20 Mohan\plain \f1\lang1033\fs20  Initia, S. 290*. Au\u223 \'dferdem in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Berlin, SBB-PK, Ms. Magdeb. 71 (Magdeburg 1444), 56}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs20\chcbpat17 ra}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 -72}}\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 , vgl. \plain \f1\scaps\lang1033\fs20 Winter\plain \f1\scaps\lang1033\fs20 ,\plain \f1\lang1033\fs20  Berlin I,4,1, S. 177; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Leipzig, UB, Ms 529 (14. Jh., 2. Viertel), 176}}{\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs20\chcbpat17 vb}}{\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 -185}}\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 , und {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Ms 534 (15. Jh., 1. Viertel), 233}}{\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs20\chcbpat