\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Zur Einf\u252 \'fchrung des Festes Visitatio BMV in der Gesamtkirche durch Papst Bonifaz IX. im Jahr 1389 und zum Autor dieses Offiziums ({\field{\*\fldinst HYPERLINK "hida://bezper[9].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Adam Esthonus}}\plain \f1\lang1033\fs20  = Kardinal \plain \f1\scaps\lang1033\fs20 Adam Easton\plain \f1\lang1033\fs20  O.S.B., \u8224 \'86 1397) vgl. James \plain \f1\scaps\lang1033\fs20 Hogg,\plain \f1\lang1033\fs20  Cardinal Adam Easton\rquote s Office for the Feast of the Visitation of the Blessed Virgin Mary, in: Lars \plain \f1\scaps\lang1033\fs20 Bisgaar\plain \f1\lang1033\fs20 , u. a. (Hg.), Medieval Spirituality in Scandinavia and Europe: A Collection of Essays in Honour of Tore Nyberg, Odense 2001, S. 219-224, v. a. S. 219 mit Anm. 3 zur \u220 \'dcberlieferung. Die Autorzuweisung best\u228 \'e4tigt das durch die Anfangsbuchstaben der Antiphonen gebildete, unvollst\u228 \'e4ndige Akrostichon ADAM CARDI[NAL]US ..., vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[27].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 AH 52, Nr. 42}}\plain \f1\lang1033\fs20 , S. 48. Zu den beiden zugeh\u246 \'f6rigen Hymnen, ebenfalls von diesem Autor s. u. 271\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -272\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 . Vgl. auch {\field{\*\fldinst HYPERLINK "hida://5007[18].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Leipzig, BVerwG, Ms. nov. 3 (olim Fragm. 35), 4o+4u}}\plain \f1\super\lang1033\fs20 ra-rb\plain \f1\lang1033\fs20 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (93\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -99\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  >\plain \f1\b\i\lang1033\fs24 De sancto {\field{\*\fldinst HYPERLINK "hida://bezper[10].4100/?u"}{\fldrslt \plain \f1\b\i\lang1033\fs24\chcbpat17 Kyliano}}\plain \f1\i\lang1033\fs24 <\plain \f1\lang1033\fs24  (08.07.). Ant. \plain \f1\i\lang1033\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[28].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 S<ancti per fidem uicerunt regna}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezlit[28].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CAO 4733}}\plain \f1\lang1033\fs24 ), (93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[29].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 F<ulgebunt iusti et tamquam scintille}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezlit[29].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CAO 2907}}\plain \f1\lang1033\fs24 ) etc. bis Ant. \plain \f1\i\lang1033\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[31].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O< precelsi bellatores Christi}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezlit[30].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CAO 203503}}\plain \f1\lang1033\fs24 ), zugeh\u246 \'f6riger Hymnus s.\~u. 293\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -294\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ;
