\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -182\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Proprium de tempore}}\plain \f1\b\lang1033\fs24 :\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Dom. 1. Adventus bis Dominica post Ascensionem\plain \f1\lang1033\fs24 , unvollst\u228 \'e4ndig.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Blatt 1 im 16. Jh., 2. H\u228 \'e4lfte [um 1578?] erg\u228 \'e4nzt) [\plain \f1\b\lang1033\fs24 Dom. 1. Adventus\plain \f1\lang1033\fs24 ] Ant. \plain \f1\i\lang1033\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 E<cce dies venient, dicit dominus, et suscitabo Dauid}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CAO 2506}}\plain \f1\lang1033\fs24 , zu Dom. 4. Adventus), \plain \f1\i\lang1033\fs24 >In evangelio ant.<\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 >E<cce nomen domini uenit de longinquo ...\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezlit[66].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CAO 2527}}\plain \f1\lang1033\fs24 ) etc. bis In II. Vesp., Ant. ad Magn. \plain \f1\i\lang1033\fs24 >N<e timeas, Maria, inuenisti gratiam ...\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezlit[66].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CAO 3863}}\plain \f1\lang1033\fs24 ), zum zugeh\u246 \'f6rigen Hymnus s. u. 290\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ;
