\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 2a\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -114\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Vetus Testamentum: Prophetae maiores et minores (Is bis I-II Mcc)\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (2a\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -17\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Is\plain \f1\lang1033\fs24 : [Prolog, Kap. 1-2 und Beginn von Kap. 3 fehlen];
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (17\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -35\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Ier\plain \f1\lang1033\fs24 : (17\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Incipit prologus Ieremie prophete<: >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 I<Eremias Anachontes }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [sonst: Anatholites]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 , qui est uiculus}}\plain \f1\i\lang1033\fs24  tribus ab Ierosolimis distans milibus ... - ... magna ei religione ibi Egipcii venerantur. \plain \f1\lang1033\fs24 (vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , RB I, Nr. 486}}\plain \f1\lang1033\fs24 , vgl. PL 114, Sp. 9B)\plain \f1\i\lang1033\fs24 ,\plain \f1\lang1033\fs24  (17\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Item alius prologus<: \plain \f1\lang1033\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 I<heremias propheta, cui hic prologus scribitur}}\plain \f1\i\lang1033\fs24 , sermone quidem apud Hebreos Ysaia et Osee et quibusdam aliis prophetis videtur esse rusticior ... - ... invidorum insaniam provocare. \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Hieronymus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Prologus in Ieremiam}}\plain \f1\lang1033\fs24 , vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , RB I, Nr. 487}}\plain \f1\lang1033\fs24 , PL 28, Sp. 847C-850A), (17\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -35\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Text;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (35\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -37\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Lam\plain \f1\lang1033\fs24 :\plain \f1\i\lang1033\fs24  >Incipiunt Treni siue Lamentationes<: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [E]}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 T factum est, postquam in captiuitatem ductus}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 [sonst: redactus] \plain \f1\i\lang1033\fs24 est Israel et Ierusalem deserta est, sedit Ieremias flens et planxit lamentationes ... \plain \f1\lang1033\fs24 (vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  RB I, Nr. 29}}\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 et eui\plain \f1\lang1033\fs24 (35\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 gilans \plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 dixit: >Alleph<. Quomodo sedet sola ciuitas plena populo ...\plain \f1\lang1033\fs24  Text;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (37\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -39\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Bar\plain \f1\lang1033\fs24 :\plain \f1\b\lang1033\fs24  \plain \f1\i\lang1033\fs24 >Incipit liber Baruch<: {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [L]}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Iber iste, qui Baruch nomine prenotatur}}\plain \f1\i\lang1033\fs24 , in Hebreo canone non habetur, sed tantum in vulgata edicione ... - ... pro vita Nabuchodonosor recta. \plain \f1\lang1033\fs24 (vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , RB I, Nr. 491}}\plain \f1\lang1033\fs24 , PL 114, Sp. 63), (37\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -37\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Text;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (39\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -39\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Wiederholung von Lam;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (42\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -62\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Ez\plain \f1\lang1033\fs24 : (42\plain \f1\super\lang1033\fs24 ra-rb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Incipit prologus Ezechielis prophete<: >{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 E<Zechiel propheta cum Ioachim, rege Iuda, captiuus ductus}}\plain \f1\i\lang1033\fs24  in Babilonem ...\plain \f1\lang1033\fs24  - ... \plain \f1\i\lang1033\fs24 Sed vereor, ne illud eis eveniat, quod Grece significantius patocliaopi \plain \f1\lang1033\fs24\cf18 [Druck: dicitur, ut vocentur fagoloivdoroi]\plain \f1\i\lang1033\fs24 , quod est, manducantes sentencias\plain \f1\lang1033\fs24  [Druck: sannas]. ({\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Hieronymus}}\plain \f1\lang1033\fs24 , vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  I, Nr. 492}}\plain \f1\lang1033\fs24 , PL 28, Sp. 937D-940A), (42\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -62\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Text;
