\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (207\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -209\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 I-III Io\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 >Incipit argumentum in \plain \f1\lang1033\fs24 [epistolam] \plain \f1\i\lang1033\fs24 canonicam sancti Johannis primam<: >{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 R<Acionem verbi, et quod deus ipse sit caritas}}\plain \f1\i\lang1033\fs24 , manifestat ... - ... quod odium sit interfectionis occasio.\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Walafridus Strabo}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Argumentum}}\plain \f1\lang1033\fs24 , vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , RB I, Nr. 822}}\plain \f1\lang1033\fs24 , PL 114, Sp. 693D), (207\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -208\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Text I Io, (208\plain \f1\super\lang1033\fs24 va-vb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Incipit argumentum in epistolam sancti Johannis secundam<: {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [U]}}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sque adeo ad sanctam feminam scripsit}}\plain \f1\i\lang1033\fs24 , ut eandem dominam ... - ... quod ambulent in veritate, perhibeat\plain \f1\lang1033\fs24 . ({\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Walafridus Strabo}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Argumentum}}\plain \f1\lang1033\fs24 , vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , RB I, Nr. 823}}\plain \f1\lang1033\fs24 , PL 114, Sp. 703D), (208\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Text II Io, \plain \f1\i\lang1033\fs24 >Incipit argumentum in epistolam sancti Johannis terciam<: {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [G]}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Aium pietatis causa extollit}}\plain \f1\i\lang1033\fs24 , atque ut in ipsa pietate maneat exhortatur ... - ... perhibet cum fratribus universis.\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Walafridus Strabo}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Argumentum}}\plain \f1\lang1033\fs24 , vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[5].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[5].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , RB I, Nr. 824}}\plain \f1\lang1033\fs24 , PL 114, Sp. 705B), (208\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -209\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Text III Io;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (209\plain \f1\super\lang1033\fs24 ra-rb\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Iud\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 >Incipit argumentum in epistolam Iude<: {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [I]}}{\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Vdas apostolus fratres de corruptoribus}}\plain \f1\i\lang1033\fs24  vie veritatis ita informat ... - ... officiis navare servilibus.\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Walafridus Strabo}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Argumentum}}\plain \f1\lang1033\fs24 , vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[6].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[6].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , RB I, Nr. 825}}\plain \f1\lang1033\fs24 , PL 114, Sp. 705D), (209\plain \f1\super\lang1033\fs24 ra-rb\plain \f1\lang1033\fs24 ) Text;}

