\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >\plain \f1\b\i\lang1033\fs24 In die Penthecostes\plain \f1\i\lang1033\fs24 <\plain \f1\lang1033\fs24 , \plain \f1\lang1033\fs20 vgl. {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Chb. III}}\plain \f1\lang1033\fs20 , 1\plain \f1\super\lang1033\fs20 r-v\plain \f1\lang1033\fs20 ;
