\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Im Folgenden bei diesem Band nur verk\u252 \'fcrzte Beschreibung, beim 1. Exemplar (Chb. V) ausf\u252 \'fchrliche Inhaltsbeschreibung und stichprobenartiger Vergleich mit dem Mei\u223 \'dfner Brevierdruck von 1502. Die Folioangaben bei Chb. IV und V differieren nur geringf\u252 \'fcgig (durch Blattverlust in Chb. IV, nach Bl. 3). 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Proprium de tempore}}\plain \f1\b\lang1033\fs24 : Vigil zu Pfingsten bis Sonntage nach Pfingsten\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >In uigilia Penthecostes<\plain \f1\lang1033\fs24 , \plain \f1\lang1033\fs20 vgl. {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Chb. V}}\plain \f1\lang1033\fs20 , 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) [\plain \f1\b\lang1033\fs24 Dominica\plain \f1\b\i\lang1033\fs24  \plain \f1\b\lang1033\fs24 Penthecostes\plain \f1\lang1033\fs24 ], \plain \f1\lang1033\fs20 vgl. Chb. V, 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -3\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Feria secunda<\plain \f1\lang1033\fs24 , \plain \f1\lang1033\fs20 [durch Blattverlust am Ende unvollst.], vgl. Chb. V, 3\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -4\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Feria tertia<\plain \f1\lang1033\fs24 , \plain \f1\lang1033\fs20 [durch Blattverlust bis auf Schluss verloren],\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs20 vgl. Chb. V, 4\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -5\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (4\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Per hebdomada sequuntur antiphone<\plain \f1\lang1033\fs24 , \plain \f1\lang1033\fs20 neuzeitliche Nachtr\u228 \'e4ge auf 4\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  mit Pergamentstreifen \u252 \'fcberklebt, vgl. Chb. V, 5\plain \f1\super\lang1033\fs20 r-v\plain \f1\lang1033\fs20 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -9\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >\plain \f1\b\i\lang1033\fs24 De sancta Trinitate\plain \f1\i\lang1033\fs24 <\plain \f1\lang1033\fs24 , \plain \f1\lang1033\fs20 vgl. Chb. V, 5\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -10\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , mit denselben R\u246 \'f6teleintr\u228 \'e4gen;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (9\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >\plain \f1\b\i\lang1033\fs24 De Corpore Christi\plain \f1\i\lang1033\fs24 <\plain \f1\lang1033\fs24 , \plain \f1\lang1033\fs20 vgl. Chb. V, 10\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -15\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >\plain \f1\b\i\lang1033\fs24 In octaua Corporis Christi\plain \f1\i\lang1033\fs24 <\plain \f1\lang1033\fs24 ,\plain \f1\lang1033\fs20  vgl. Chb. V, 15\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ;}

