\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Z. 8-26) [\plain \f1\b\lang1033\fs24 cap. 3-5\plain \f1\lang1033\fs24 :] \plain \f2\i\lang1024\fs24 Ad hanc, qu\u281 \'ea hinc excreuerit, \plain \f1\lang1033\fs24 [summam, 4 embada, quae faciunt 600 adiicia]\plain \f3\i\fs24 ntur. Qu\u281 \'e6 coniunctio \u299 \'eeccxxv \plain \f1\lang1033\fs24 [1225]\plain \f1\i\lang1033\fs24  repr\plain \f2\i\lang1024\fs24 \u281 \'ea\plain \f1\i\lang1033\fs24 sentat. ... - ... \plain \f1\lang1033\fs24 [... cuius lateribus numeri qu]\plain \f1\i\lang1033\fs24 antitate dissimiles sint distributi, minori scilicet \plain \f1\lang1033\fs24 [hypotenusae 13, basi 14, maiori vero hypotenusae 15, ejusdem oxygonii si perp]\plain \f1\i\lang1033\fs24 endicularem inuenire desideras\plain \f1\lang1033\fs24 , [bricht ab: et praescissuras dignoscere singulas, ...].
